<?php

namespace App\Support;

use App\Models\Product;
use Illuminate\Support\Str;

/** Slugs generated by store writers must round-trip through the 255-character edit field. */
class ProductSlug
{
    /**
     * The slug, numbered after the other products whose slug begins with it,
     * as ProductService::store() numbered it.
     */
    public static function numbered(string $slug, ?int $ignore): string
    {
        $slug = Str::substr($slug, 0, 255);
        if ($slug === '') {
            $slug = 'product-'.Str::lower(Str::random(12));
        }
        $sameSlugCount = Product::query()->where('slug', 'like', $slug.'%')
            ->when($ignore !== null, fn ($query) => $query->whereKeyNot($ignore))->count();
        $number = $sameSlugCount ? $sameSlugCount + 1 : 0;
        do {
            $suffix = $number ? '-'.$number : '';
            $candidate = Str::substr($slug, 0, 255 - strlen($suffix)).$suffix;
            if (! Product::query()->where('slug', $candidate)
                ->when($ignore !== null, fn ($query) => $query->whereKeyNot($ignore))->exists()) {
                return $candidate;
            }
            $number = $number > 0 ? $number + 1 : 2;
        } while (true);
    }

    public static function duplicate(?string $slug): string
    {
        $base = Str::slug($slug ?? '') ?: 'product';

        return self::numbered(Str::substr($base, 0, 249).'-'.Str::lower(Str::random(5)), null);
    }
}
